'use client';
import React from 'react';

import EmojiPicker from 'emoji-picker-react';

// The default picker in reactions mode with Slack's common reaction set.
// The "+" expands to the full picker in place.
export type PickerExampleProps = {
  /** The picker root: EmojiPicker, or a styled() wrapper of it. */
  Root?: React.ComponentType<Omit<React.ComponentProps<typeof EmojiPicker>, 'theme'>>;
  className?: string;
};

export function PickerExample({
  Root: RootComponent = EmojiPicker,
  className,
}: PickerExampleProps) {
  return (
    <RootComponent
      className={className}
      reactionsDefaultOpen
      reactions={['2705', '1f440', '1f64c', '1f525', '1f389', '1f44d']}
      width={420}
      height={380}
    />
  );
}

/* Slack — message reactions: a fixed quick-reaction bar that expands into a
   full picker, in Slack's aubergine and Lato-like type. */
/* Picker styles — the source of truth for every stack variant. */
.slack-picker {
  --epr-bg-color: #ffffff;
  --epr-reactions-bg-color: #ffffff;
  --epr-text-color: #1d1c1d;
  --epr-highlight-color: #1264a3;
  --epr-hover-bg-color: #f8f8f8;
  --epr-focus-bg-color: #e8f5fa;
  --epr-picker-border-color: #dddddd;
  --epr-search-input-bg-color: #ffffff;
  --epr-search-border-color: #868686;
  --epr-search-border-color-active: #1264a3;
  --epr-category-icon-active-color: #1264a3;
  --epr-category-label-text-color: #616061;
  --epr-category-label-bg-color: #ffffffee;
  --epr-picker-border-radius: 8px;
  margin-left: 46px;
  box-shadow: 0 4px 12px rgb(0 0 0 / 12%);
  font-family: inherit;
}
.slack-picker [data-epr-part='category-label'] {
  font-size: 13px;
  font-weight: 700;
  text-transform: none;
}
.slack-picker [data-epr-part='reactions'] {
  padding: 0 6px;
}
.slack-picker [data-epr-part='reaction'] {
  border-radius: 6px;
}

